// ─────────────────────────────────────────────────────────────────────────────
// src/data/faqData.mjs — LIVE FAQ ENGINE (single source of truth)
//
// There is NO hand-written list of questions with frozen answers any more.
// Every Q&A is GENERATED by buildFaqItems(live) from the school's own database
// (the same tables the admin dashboard edits):
//
//   school_settings · admission_settings · admission_class_seats ·
//   admission_merit_lists · grading_schemes · library_files (Admission) ·
//   results / merit_lists / exam_roll_sessions metadata · notices ·
//   teachers · faq_entries (optional, admin-written extra Q&A)
//
// WHO USES IT (one engine → zero drift)
//   1. api/render.js   → builds `live` from Supabase, exposes it as
//        GET /api/faq (JSON), inside /api/ai-data, in the crawler HTML of
//        /faq, in /llms.txt, /llms-full.txt and the Markdown pages.
//   2. src/hooks/useLiveFaq.ts → the /faq page and the FAQPage JSON-LD fetch
//        /api/faq, so humans, Google and AI tools see IDENTICAL text.
//   3. scripts/seo-page-content.mjs → build-time fallback uses FAQ_ITEMS
//        (= buildFaqItems(null)): the "no live data" rendering. It never
//        states a number, date, fee or status — it points to the live source.
//
// RULES
//   • A fact is only stated when it comes from `live` or from the website's
//     own behaviour (routes/flows that exist in the code). Anything that can
//     change (fee, deadline, seats, status, phone, principal, grading, exams,
//     staff) is read from `live` — never typed here.
//   • A question that has no data behind it is simply not generated.
//   • Pure functions, no I/O, no Node/DOM APIs → safe in the browser, Vercel
//     functions and the build scripts.
// ─────────────────────────────────────────────────────────────────────────────

export const FAQ_CATEGORIES = [
  "Admissions",
  "Results & Exams",
  "School Information",
  "Website & Contact",
];

const SITE = "https://ghsbabikhel.dpdns.org";

// ── small helpers ───────────────────────────────────────────────────────────
const has = (v) => v !== null && v !== undefined && String(v).trim() !== "";
const num = (v) => (typeof v === "number" && Number.isFinite(v) ? v : null);
const rs = (n) => `Rs ${Number(n).toLocaleString("en-PK")}`;

function fmtDate(iso) {
  if (!iso) return "";
  const d = new Date(String(iso).length <= 10 ? `${iso}T12:00:00+05:00` : iso);
  if (Number.isNaN(d.getTime())) return "";
  try {
    return new Intl.DateTimeFormat("en-GB", {
      timeZone: "Asia/Karachi",
      day: "numeric",
      month: "long",
      year: "numeric",
    }).format(d);
  } catch {
    return String(iso).slice(0, 10);
  }
}

function joinList(items) {
  const a = items.filter(Boolean);
  if (a.length <= 1) return a.join("");
  if (a.length === 2) return `${a[0]} and ${a[1]}`;
  return `${a.slice(0, -1).join(", ")} and ${a[a.length - 1]}`;
}

/** "6, 7, 8" → "6, 7 and 8" — classes sorted numerically. */
function classList(rows) {
  const c = rows
    .map((r) => String(r.class))
    .sort((a, b) => Number(a) - Number(b));
  return joinList(c);
}

/** Payment METHOD names only (never account numbers / IBANs / phone numbers). */
function paymentMethodNames(accounts) {
  const names = [];
  for (const a of Array.isArray(accounts) ? accounts : []) {
    if (!a) continue;
    let n = "";
    if (a.type === "easypaisa") n = "Easypaisa";
    else if (a.type === "jazzcash") n = "JazzCash";
    else if (a.type === "bank") n = a.bank_name ? `bank transfer (${a.bank_name})` : "bank transfer";
    else if (a.type === "cash") n = "cash at the school office";
    else n = a.label || "";
    if (n && !names.includes(n)) names.push(n);
  }
  return names;
}

/** Normalise whatever the server/client hands in into one predictable shape. */
export function normalizeFaqLive(raw) {
  if (!raw || typeof raw !== "object") return null;
  const school = raw.school || {};
  const adm = raw.admission || {};
  return {
    school: {
      name: school.name || null,
      full_name: school.full_name || null,
      location: school.location || null,
      established: has(school.established) ? String(school.established) : null,
      emis_code: has(school.emis_code) ? String(school.emis_code) : null,
      principal: school.principal || null,
      phone: school.phone || null,
      email: school.email || null,
      board: school.board || null,
      classes_offered: Array.isArray(school.classes_offered) ? school.classes_offered : null,
      total_students: num(school.total_students),
      total_teachers: num(school.total_teachers),
      pass_percentage: num(school.pass_percentage),
    },
    admission: {
      currently_open: typeof adm.currently_open === "boolean" ? adm.currently_open : null,
      session_year: adm.session_year || null,
      open_date: adm.open_date || null,
      last_date: adm.last_date || null,
      banner_message: adm.banner_message || null,
      processing_fee: num(adm.processing_fee),
      online_payment_enabled:
        typeof adm.online_payment_enabled === "boolean" ? adm.online_payment_enabled : null,
      payment_methods: Array.isArray(adm.payment_methods) ? adm.payment_methods : [],
      contact_whatsapp: adm.contact_whatsapp || null,
    },
    classes: Array.isArray(raw.classes) ? raw.classes : null,
    admissionMerit: Array.isArray(raw.admissionMerit) ? raw.admissionMerit : [],
    grading: raw.grading && Array.isArray(raw.grading.ranges) ? raw.grading : null,
    exams: Array.isArray(raw.exams) ? raw.exams : [],
    bisep: raw.bisep && raw.bisep.exam_title ? raw.bisep : null,
    schoolMerit: Array.isArray(raw.schoolMerit) ? raw.schoolMerit : [],
    rollSlips: Array.isArray(raw.rollSlips) ? raw.rollSlips : [],
    teacherCount: num(raw.teacherCount),
    teacherSubjects: Array.isArray(raw.teacherSubjects) ? raw.teacherSubjects : [],
    noticeCount: num(raw.noticeCount),
    latestNotice: raw.latestNotice || null,
    customFaqs: Array.isArray(raw.customFaqs) ? raw.customFaqs : [],
    generated_at: raw.generated_at || null,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// THE GENERATOR
// ─────────────────────────────────────────────────────────────────────────────
export function buildFaqItems(rawLive = null) {
  const L = normalizeFaqLive(rawLive); // null → "no live data" (build-time) mode
  const live = !!L;
  const s = L?.school || {};
  const a = L?.admission || {};
  const items = [];
  const add = (id, category, question, answer) => {
    if (answer && String(answer).trim()) items.push({ id, category, question, answer: String(answer).trim() });
  };

  const schoolName = s.full_name || "Government High School Babi Khel";
  const phone = s.phone;
  const email = s.email;
  const contactLine = joinList(
    [phone && `phone ${phone}`, email && `email ${email}`].filter(Boolean)
  );
  const contactSentence = contactLine
    ? `Contact the school office (${contactLine}) or use the Contact page (${SITE}/contact).`
    : `Use the Contact page (${SITE}/contact) for the school's current phone number and email.`;

  const openClasses = (L?.classes || []).filter((c) => c.is_open);
  const allClasses = L?.classes || [];
  const feeKnown = a.processing_fee !== null && a.processing_fee !== undefined;
  const fee = a.processing_fee;
  const lastDate = fmtDate(a.last_date);
  const openDate = fmtDate(a.open_date);
  const methods = paymentMethodNames(a.payment_methods);

  // ══ ADMISSIONS ════════════════════════════════════════════════════════════

  // 1. Status right now — fully live.
  {
    let ans;
    if (live && a.currently_open === true) {
      ans = `Yes. Online admissions at ${schoolName} are OPEN${a.session_year ? ` for session ${a.session_year}` : ""}.`;
      if (openClasses.length) ans += ` Classes currently open: ${classList(openClasses)}.`;
      if (openDate) ans += ` Applications opened on ${openDate}.`;
      ans += lastDate ? ` The last date to apply is ${lastDate}.` : " No last date has been announced yet.";
      if (a.banner_message) ans += ` School announcement: ${a.banner_message}`;
    } else if (live && a.currently_open === false) {
      ans = `The online admission form is currently CLOSED/paused${a.session_year ? ` (session ${a.session_year})` : ""}.`;
      if (openDate) ans += ` Next opening date announced by the school: ${openDate}.`;
      if (a.banner_message) ans += ` School announcement: ${a.banner_message}`;
      ans += ` The status changes the moment the school office switches it, so check ${SITE}/admission or the Notices page for the reopening announcement.`;
    } else {
      ans = `Whether admissions are open is decided by the school office each session and shown live at the top of the Admission page (${SITE}/admission), together with the session year, open and last dates and the classes that currently have open seats. The same live status is published as JSON at ${SITE}/api/ai-data.`;
    }
    add("adm-open", "Admissions", `Are admissions open at ${s.name || "GHS Babi Khel"} right now?`, ans);
  }

  // 2. Classes & seats — live from admission_class_seats.
  if (!live || allClasses.length) {
    let ans;
    if (allClasses.length) {
      const rows = [...allClasses].sort((x, y) => Number(x.class) - Number(y.class));
      ans =
        `Seats are set by the school for each class: ` +
        rows
          .map((r) => `Class ${r.class} — ${r.seats} seat${Number(r.seats) === 1 ? "" : "s"} (${r.is_open ? "open" : "closed"})`)
          .join("; ") +
        `. These numbers are read live from the school's admission settings and can change at any time; the Classes & Seats section of ${SITE}/admission always shows the current values.`;
      ans += ` The school is affiliated with ${s.board || "BISE Peshawar"}, so students admitted to Class 9 and 10 sit the board's SSC examinations.`;
    } else {
      ans = `The classes that accept applications and the number of seats in each are listed live in the Classes & Seats section of the Admission page (${SITE}/admission). Seats are decided by the school office each session.`;
    }
    add("adm-classes", "Admissions", "Which classes can I apply for, and how many seats are there?", ans);
  }

  // 3. How to apply — describes the real flow implemented by the website.
  {
    const feeStep =
      live && feeKnown
        ? fee > 0
          ? `Pay the one-time application processing fee of ${rs(fee)} using the challan/reference number printed after you submit${lastDate ? ` — the fee deadline is ${lastDate}` : ""}${methods.length ? `; accepted methods: ${joinList(methods)}` : ""}${a.online_payment_enabled ? "; online payment is available on the tracker" : ""}.`
          : "No processing fee is currently charged for the application."
        : "If the school has set an application processing fee, the amount, the challan and the payment options appear after you submit — the fee is shown live on the Admission page.";
    const ans =
      `Step 1: open ${SITE}/admission and use the eligibility check, then fill the application — student name, father name, date of birth, B-Form number, contact number, gender, the class you apply for, admission type (fresh or migration) and previous-school details. ` +
      `Step 2: submit — the website immediately issues a reference number; keep it. ` +
      `Step 3: ${feeStep} ` +
      `Step 4: the school office verifies the application and the fee. ` +
      `Step 5: seats in each class are filled through the admission Merit List, which ranks eligible applicants on their previous-class marks; merit-listed students then submit their original documents at the school office to complete enrolment. ` +
      `You can also use the offline route: download and print the admission form from the Admission page, fill it by hand, attach photocopies of the documents and submit it in person at the school office.`;
    add("adm-how", "Admissions", "How do I apply for admission online, step by step?", ans);
  }

  // 4. Documents.
  add(
    "adm-documents",
    "Admissions",
    "Which documents are required for admission?",
    "For every applicant: the student's B-Form (NADRA), a recent passport-size photograph, the previous class result card/marksheet where applicable, the father's or guardian's CNIC copy, and a School Leaving Certificate (SLC) — under the school's admission policy the SLC is required for ALL admissions, both fresh and migration. " +
      "For Class 9 or 10 students migrating from another BISE-affiliated school or another board, the schools additionally handle the DMC, migration certificate and an enrollment/reference letter from the previous school's head on the BISE Peshawar portal. " +
      `The official Admission Prospectus and Admission Rules on ${SITE}/admission are the authoritative list for the current session.`
  );

  // 5. Fee — live. (Previously a hard-coded "completely free" claim.)
  {
    let ans;
    if (live && feeKnown && fee > 0) {
      ans =
        `Tuition: the school follows the Government of Khyber Pakhtunkhwa free-education policy for government schools, and any school-level charge is confirmed by the school office. ` +
        `Application: a one-time admission processing fee of ${rs(fee)} applies to every online application${lastDate ? ` and must be paid by ${lastDate}` : ""}. ` +
        (methods.length ? `Payment options configured by the school: ${joinList(methods)}${a.online_payment_enabled ? " (online checkout is enabled)" : ""}. ` : "") +
        `Only applications whose processing fee is marked PAID by the office are ranked in the merit list. ` +
        `BISE Peshawar charges for Class 9/10 (enrolment or migration) are board fees paid through the board's own channels, not to the school.`;
    } else if (live && feeKnown && fee === 0) {
      ans =
        `No application processing fee is currently set for online applications. Tuition follows the Government of Khyber Pakhtunkhwa free-education policy for government schools, and any school-level charge is confirmed by the school office. BISE Peshawar charges for Class 9/10 (enrolment or migration) are board fees paid through the board's own channels. The setting is live — check ${SITE}/admission for the current amount.`;
    } else {
      ans =
        `Tuition follows the Government of Khyber Pakhtunkhwa free-education policy for government schools. The online application may carry a one-time processing fee set by the school office each session; the exact current amount, deadline and payment options are shown live on the Admission page (${SITE}/admission) and at ${SITE}/api/ai-data. BISE Peshawar charges for Class 9/10 are board fees paid through the board's own channels.`;
    }
    add("adm-fee", "Admissions", "Is there any admission fee or tuition fee?", ans);
  }

  // 6. Tracking.
  add(
    "adm-track",
    "Admissions",
    "How can I track my admission application status?",
    `Open ${SITE}/admission, go to Track Application and search with your reference number, your B-Form number or your contact number — any one works. ` +
      `For the full personal dashboard (status timeline, fee/challan, merit-list outcome, school notes) open the Applicant Portal at ${SITE}/admission/portal and enter your reference number together with the B-Form number. ` +
      `Statuses you may see: pending, under review, documents missing, documents verified, interview scheduled/completed, waitlisted, merit listed, approved, rejected, admitted and admit card issued.`
  );

  // 7. Merit list (admission) — live when lists are published.
  {
    const pub = (L?.admissionMerit || []).filter((m) => m);
    let ans =
      "Admission merit lists are prepared per class. The office ranks applicants whose processing fee is paid by their previous-class marks/percentage; the top applicants, up to the number of seats left in that class, are merit-listed, the rest are not listed. A class can have several numbered lists as seats remain.";
    if (pub.length) {
      ans +=
        ` Currently published: ` +
        pub
          .slice(0, 12)
          .map((m) => `${m.title || `Class ${m.class} list ${m.list_no}`}${m.published_at ? ` (${fmtDate(m.published_at)})` : ""}${Number.isFinite(m.listed_count) ? ` — ${m.listed_count} listed` : ""}`)
          .join("; ") +
        ".";
    } else if (live) {
      ans += " No admission merit list is published at this moment.";
    }
    ans += ` Published lists are on ${SITE}/admission.`;
    add("adm-merit", "Admissions", "How are admission seats filled — what is the admission merit list?", ans);
  }

  // 8. Migration.
  add(
    "adm-migration",
    "Admissions",
    "How does migration or transfer to this school work for class 9 and 10?",
    "School-level approval of your online application and board-level migration are two separate steps. After you are approved at the school, migration between BISE Peshawar-affiliated institutions (or from another board) is carried out on the BISE Peshawar portal by the sending and receiving schools within the board's notified migration window for the academic year — a parent or student does not complete it by submitting a form to the board directly. A valid School Leaving Certificate is required. For students coming from another board, the receiving school submits the DMC, migration certificate and an enrollment/reference letter from the previous school's head to BISE Peshawar with the prescribed board fee. For classes 6 to 8 a transfer is handled between the schools and does not go through the BISE Peshawar portal."
  );

  // ══ RESULTS & EXAMS ═══════════════════════════════════════════════════════

  // Exams actually published (live).
  {
    const exams = L?.exams || [];
    let ans =
      `Open ${SITE}/results, choose the exam (class and examination name) and enter the roll number exactly as printed on the admit card. The result card shows total and obtained marks, percentage, grade, pass/fail status and class position. Results appear only after the school administration publishes them, so a roll number that is not found usually means the exam is not published yet.`;
    if (exams.length) {
      const list = exams
        .slice(0, 10)
        .map((e) => `${e.exam}${e.class ? ` (Class ${e.class})` : ""}${e.year ? ` ${e.year}` : ""}`)
        .join("; ");
      ans += ` Published right now: ${list}.`;
    } else if (live) {
      ans += " No school exam result is published at this moment.";
    }
    add("res-check", "Results & Exams", "How do I check my exam result on the website?", ans);
  }

  // BISE Peshawar — live exam title / countdown.
  {
    let ans =
      `The Results page (${SITE}/results) searches BISE Peshawar board results for SSC (9th and 10th class) by roll number and fetches them live from the board's official portal (cloud.bisep.edu.pk); the website does not store board results.`;
    if (L?.bisep) {
      const b = L.bisep;
      if (b.is_live) ans += ` Current cycle: ${String(b.exam_title).trim()} — results are LIVE now.`;
      else if (b.countdown_date) {
        const d = new Date(b.countdown_date);
        if (!Number.isNaN(d.getTime())) {
          let when = "";
          try {
            when = new Intl.DateTimeFormat("en-GB", {
              timeZone: "Asia/Karachi", day: "numeric", month: "long", year: "numeric", hour: "2-digit", minute: "2-digit", hour12: true,
            }).format(d);
          } catch { when = d.toISOString(); }
          ans += ` Current cycle: ${String(b.exam_title).trim()} — announcement scheduled for ${when} (Pakistan time); a live countdown is shown on the page.`;
        }
      } else ans += ` Current cycle on the board portal: ${String(b.exam_title).trim()}.`;
    }
    ans += " For rechecking, certificates or anything beyond the displayed result, contact BISE Peshawar or the school office.";
    add("res-bisep", "Results & Exams", "How do I check my BISE Peshawar board result?", ans);
  }

  // Grading scale — live from grading_schemes (falls back to the app default).
  if (L?.grading) {
    const g = L.grading;
    const parts = g.ranges
      .filter((r) => r.grade)
      .map((r) => (r.grade === "Fail" ? `Fail below ${Number(g.pass_threshold ?? r.max_percentage + 1)}%` : `${r.grade} for ${r.min_percentage}–${r.max_percentage}%`));
    add(
      "res-grades",
      "Results & Exams",
      "What is the grading scale used for results?",
      `The grading scale currently active in the school's results system${g.name ? ` ("${g.name}")` : ""} is: ${parts.join(", ")}. A pass requires at least ${g.pass_threshold ?? 33}%. Each result card also shows the class position and a subject-wise breakdown of marks. The scale is read live from the school's grading settings, so it is always the one used to grade the published results.`
    );
  } else if (!live) {
    add(
      "res-grades",
      "Results & Exams",
      "What is the grading scale used for results?",
      `Grades are assigned from the percentage using the grading scheme the school activates in its results system; the current scale and pass mark are published live at ${SITE}/api/ai-data (results.grading). Each result card shows grade, class position and the subject-wise marks.`
    );
  }

  // Date sheets, notices.
  {
    let ans = `Exam schedules, date sheets, holidays and circulars are published as official notices on ${SITE}/notices. Urgent announcements are highlighted on the homepage and can be received as push notifications.`;
    if (L?.latestNotice?.title) ans += ` The most recent notice is "${L.latestNotice.title}"${L.latestNotice.published_at ? ` (${fmtDate(L.latestNotice.published_at)})` : ""}.`;
    if (L && L.noticeCount !== null) ans += ` ${L.noticeCount} notice${L.noticeCount === 1 ? " is" : "s are"} currently published.`;
    add("res-datesheet", "Results & Exams", "Where can I find exam dates, date sheets and the exam schedule?", ans);
  }

  // Roll no slip — live sessions.
  {
    const slips = L?.rollSlips || [];
    const liveSlips = slips.filter((x) => x.status === "live");
    const sched = slips.filter((x) => x.status === "scheduled");
    let ans =
      `Open the Roll No. Slip page (${SITE}/roll-no-slip), pick your class and type your full name exactly as the school recorded it (capitalisation and extra spaces do not matter). Only your own slip appears — no student can see another student's slip. The slip shows your exam roll number and QR code, your class's exam date sheet and the exam-day instructions, and can be downloaded as a PDF or shared. Bring it to every paper. For BISE Peshawar board exams (class 9 and 10) the official roll number is on the board admit card issued by the school.`;
    if (liveSlips.length) ans += ` Live now: ${liveSlips.map((x) => x.title).filter(Boolean).join("; ")}.`;
    if (sched.length)
      ans += ` Scheduled: ${sched.map((x) => `${x.title}${x.publish_at ? ` (publishes ${fmtDate(x.publish_at)})` : ""}`).join("; ")} — the page shows a live countdown and the slips appear automatically when it reaches zero.`;
    if (live && !liveSlips.length && !sched.length) ans += " No roll number slip session is published or scheduled at this moment.";
    add("res-rollslip", "Results & Exams", "How do I get my exam roll number slip?", ans);
  }

  // School merit list (results rankings) — live.
  {
    const lists = L?.schoolMerit || [];
    let ans =
      `The Merit List page (${SITE}/merit-list) shows the official examination rankings published by the school office — top position holders per class and, for some exams, school-wide — with each listed student's position, name, class, obtained marks, percentage and grade plus summary statistics (students, passed, highest and average percentage). A scheduled list shows a live countdown and appears automatically at zero; a published list can be shared as a merit card.`;
    if (lists.length)
      ans += ` Published now: ${lists.slice(0, 8).map((m) => `${m.title}${m.total_students != null ? ` (${m.total_students} students${m.passing_count != null ? `, ${m.passing_count} passed` : ""})` : ""}`).join("; ")}.`;
    else if (live) ans += " No results merit list is published at this moment.";
    add("res-meritlist", "Results & Exams", "What is the Merit List page and who appears on it?", ans);
  }

  add(
    "res-recheck",
    "Results & Exams",
    "What if I think there is a mistake in my result?",
    "For a school-conducted exam, contact the school office or your subject teacher so the marks can be verified against the answer sheet. For a BISE Peshawar board result (SSC-I or SSC-II), rechecking and reappraisal requests must be submitted to BISE Peshawar within the board's notified window — the school website only displays the board's published result and cannot change it."
  );

  // ══ SCHOOL INFORMATION ════════════════════════════════════════════════════
  {
    const bits = [];
    bits.push(`${schoolName} is a government high school${s.location ? ` located at ${s.location}` : " in District Mohmand, Khyber Pakhtunkhwa, Pakistan"}.`);
    if (s.established) bits.push(`It was established in ${s.established}.`);
    if (s.emis_code) bits.push(`EMIS code: ${s.emis_code}.`);
    const cls = s.classes_offered?.length ? joinList(s.classes_offered) : null;
    if (cls) bits.push(`It offers classes ${cls}.`);
    bits.push(`Classes 9 and 10 sit the ${s.board || "BISE Peshawar"} board examinations.`);
    if (s.principal) bits.push(`The principal is ${s.principal}.`);
    const st = [];
    if (s.total_students !== null) st.push(`${s.total_students}+ students`);
    if (s.total_teachers !== null) st.push(`${s.total_teachers} teachers`);
    if (s.pass_percentage !== null) st.push(`${s.pass_percentage}% pass rate`);
    if (st.length) bits.push(`School statistics set by the administration: ${st.join(", ")}.`);
    add("sch-about", "School Information", "Where is the school located and what kind of school is it?", bits.join(" "));
  }

  add(
    "sch-timing",
    "School Information",
    "What are the school timings and when is the office open?",
    `Daily timings change with the season and government notifications, so they are announced officially on the Notices page (${SITE}/notices) rather than fixed in this FAQ. ${contactSentence}`
  );

  {
    let ans = `The staff directory (${SITE}/teachers) lists the active teaching staff with their subjects and qualifications as entered by the school office.`;
    if (L?.teacherCount) ans += ` It currently lists ${L.teacherCount} teacher${L.teacherCount === 1 ? "" : "s"}.`;
    if (L?.teacherSubjects?.length) ans += ` Subjects taught by the listed staff: ${joinList(L.teacherSubjects.slice(0, 20))}.`;
    if (s.principal) ans += ` The school is led by principal ${s.principal}.`;
    add("sch-teachers", "School Information", "Who are the teachers and what subjects do they cover?", ans);
  }

  add(
    "sch-duties",
    "School Information",
    "What is the Exam Duties page?",
    `The Exam Duties page (${SITE}/duties) is for teachers: it shows the BISE Peshawar supervisory exam duty draw — a teacher checks the theory or practical duty by CNIC or mobile number and can download or share the duty order as a PDF. It is not a student page.`
  );

  // ══ WEBSITE & CONTACT ═════════════════════════════════════════════════════
  add(
    "web-pwa",
    "Website & Contact",
    "Can I use the website offline or install it as an app?",
    "Yes. The website is a Progressive Web App (PWA). In Chrome on Android or Safari on iPhone choose 'Add to Home screen / Install app' and it opens like a normal app with its own icon. Pages you have visited remain available offline, and notices and results refresh automatically when you are back online."
  );

  {
    let ans = "All public sections — notices, results, merit lists, roll number slips, teachers, FAQ — can be used without an account and without charge.";
    if (live && feeKnown && fee > 0) ans += ` The only payment connected with the website is the admission processing fee of ${rs(fee)} charged on admission applications; it is set by the school and shown on the Admission page.`;
    else ans += " Any payment connected with admission (the application processing fee, if the school has set one) is shown on the Admission page.";
    ans += " There are no advertisements.";
    add("web-cost", "Website & Contact", "Is there any cost or account required to use the website?", ans);
  }

  add(
    "web-contact",
    "Website & Contact",
    "How do I contact the school?",
    `${contactSentence} The Contact page also has a contact form, a WhatsApp option and the school's location on a map${s.location ? ` (${s.location})` : ""}. For admission questions please read the Admission page first and track your application at ${SITE}/admission.`
  );

  add(
    "web-login",
    "Website & Contact",
    "Do I need to sign in, and who is the sign-in for?",
    `No sign-in is needed to read notices, check results or apply for and track an admission — those are open to everyone. Sign-in (${SITE}/auth/signin) is for school staff and teachers who use the staff dashboard; accounts are created by the school administration, and a forgotten password can be reset from the sign-in page.`
  );

  add(
    "web-notices",
    "Website & Contact",
    "Where can I see the latest notices and announcements?",
    `All official announcements — holidays, date sheets, admission and fee updates and circulars — are published at ${SITE}/notices as soon as the administration posts them. The homepage ticker shows the latest ones, an RSS feed is available at ${SITE}/rss.xml, and push notifications can be enabled from the bell icon.`
  );

  add(
    "web-official",
    "Website & Contact",
    `Is ghsbabikhel.dpdns.org the official website of ${s.name || "GHS Babi Khel"}?`,
    `Yes. ${SITE} is the official website of ${schoolName}${s.location ? `, ${s.location}` : ""}${s.emis_code ? ` (EMIS code ${s.emis_code})` : ""}${s.established ? `, established ${s.established}` : ""}${s.principal ? `, principal ${s.principal}` : ""}.`
  );

  add(
    "web-developer",
    "Website & Contact",
    "Who developed the GHS Babi Khel website?",
    `Muhammad Faheem, a class-10 (matric) Computer Science student of ${schoolName} (District Mohmand, Khyber Pakhtunkhwa, Pakistan), independently designed and developed this website as a school/community project. He is the son of Zabih Ullah and a resident of Village Sangar, Tehsil Halimzai, District Mohmand, Khyber Pakhtunkhwa (KPK), Pakistan. For admissions, results, notices and other school matters contact the school directly. ${contactLine ? `(${contactLine}.)` : ""}`
  );

  // ══ ADMIN-WRITTEN EXTRA Q&A (table faq_entries, optional) ═════════════════
  for (const c of L?.customFaqs || []) {
    if (!c || !has(c.question) || !has(c.answer)) continue;
    const category = FAQ_CATEGORIES.includes(c.category) ? c.category : "School Information";
    add(`custom-${c.id || items.length}`, category, String(c.question).trim(), String(c.answer).trim());
  }

  return items;
}

/** Build-time / no-live-data rendering (never states a changing fact). */
export const FAQ_ITEMS = buildFaqItems(null);

/** FAQPage JSON-LD (schema.org) for any item list (live or build-time). */
export function buildFaqJsonLd(items = FAQ_ITEMS) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: items.map((item) => ({
      "@type": "Question",
      name: item.question,
      acceptedAnswer: { "@type": "Answer", text: item.answer },
    })),
  };
}
